<div class="page-heading"><div><p class="context">Suivi des marchandises</p><h1>Traçabilité des lots</h1><p>Retrouvez la réception d’origine et chaque mouvement jusqu’au camion sortant.</p></div></div>
<form method="get" class="filters"><input type="hidden" name="page" value="trace"><?php selectField('lot_id','Lot',$catalog->options('lot'),$_GET['lot_id']??''); ?><button>Retracer le lot</button></form>
<?php if(!empty($_GET['lot_id'])):$lot=$db->one('SELECT l.*,a.sku,a.name,o.name owner_name FROM lot l JOIN article a ON a.id=l.article_id JOIN owner o ON o.id=a.owner_id WHERE l.id=?',[(int)$_GET['lot_id']]); ?>
<section class="panel"><h2><?= h($lot['code'].' / '.$lot['sku']) ?></h2><p><?= h($lot['name'].' · '.$lot['owner_name']) ?></p><p>DLC : <?= h($lot['expires_on']??'Absente') ?> · <?= $lot['blocked']?'Bloqué : '.h($lot['block_reason']):'Non bloqué' ?></p>
<h3>Réceptions d’origine</h3><?php dataTable($db->all('SELECT r.reference reception,s.name fournisseur,v.reference camion_entrant,i.pallet_code palette,i.accepted_qty accepte,i.damaged_qty endommage,i.reservation reserve,r.validated_at validation FROM receipt_item i JOIN receipt_line rl ON rl.id=i.line_id JOIN receipt r ON r.id=rl.receipt_id JOIN supplier_notice n ON n.id=r.notice_id JOIN supplier s ON s.id=n.supplier_id JOIN truck_visit v ON v.id=r.visit_id WHERE i.lot_id=?',[$lot['id']])); ?>
<h3>Réserves des réceptions concernées</h3><p>Les réserves générales concernent la livraison ; celles des lignes concernent tous les lots de cette ligne. Un manquant total sans lot reste consultable depuis son avis et sa réception.</p><?php dataTable($db->all('SELECT x.kind type,x.reason motif,x.created_at date,u.name auteur,r.reference reception FROM receipt_reserve x LEFT JOIN receipt_line rl ON rl.id=x.line_id JOIN receipt r ON r.id=COALESCE(x.receipt_id,rl.receipt_id) JOIN user_account u ON u.id=x.actor_id WHERE EXISTS (SELECT 1 FROM receipt_item i JOIN receipt_line il ON il.id=i.line_id WHERE i.lot_id=? AND ((x.line_id IS NOT NULL AND i.line_id=x.line_id) OR (x.receipt_id IS NOT NULL AND il.receipt_id=x.receipt_id))) ORDER BY x.created_at,x.id',[$lot['id']])); ?>
<h3>Emplacements et sorties</h3><?php $p=max(1,(int)($_GET['p']??1));$stmt=$db->run('CALL trace_lot(?,?)',[$lot['id'],($p-1)*20]);$history=$stmt->fetchAll();$stmt->closeCursor();dataTable($history);$total=(int)$db->scalar('SELECT COUNT(*) FROM stock_movement m JOIN receipt_item i ON i.id=m.receipt_item_id WHERE i.lot_id=?',[$lot['id']]);pagination($total,$p); ?>
<h3>Réservations et commandes</h3><?php dataTable($db->all('SELECT o.reference commande,i.pallet_code palette,l.code emplacement,p.qty quantite,p.status etat,s.reference expedition,v.reference camion_sortant FROM pick p JOIN receipt_item i ON i.id=p.receipt_item_id JOIN order_line ol ON ol.id=p.order_line_id JOIN customer_order o ON o.id=ol.order_id JOIN location l ON l.id=p.location_id LEFT JOIN shipment s ON s.order_id=o.id LEFT JOIN truck_visit v ON v.id=s.visit_id WHERE i.lot_id=? ORDER BY o.reference',[$lot['id']])); ?></section><button class="secondary no-print" type="button" data-print>Imprimer la traçabilité</button><?php endif; ?>
